# Check the T5 home-builder and converter listings against the stock image,
# and the 15-byte profile swap against the Z5 overlay CSV.
# Copies that CSV to work/out/overlay-changed-bytes.csv.
# Do not edit this file after it has run.
import csv
import re
import struct
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
BASE = 0x60021020
HOME_LISTING = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/disasm-home-k1.txt'
CONV_LISTING = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/disasm-converter-k1.txt'
Z5_CSV = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes-c1.csv'
OUT_CSV = ROOT / 'work/out/overlay-changed-bytes.csv'
OUT = ROOT / 'work/out/listing-check-t6.txt'

SWAP_AT = 0x60A8F708
SWAP_LEN = 20
# Documented Z5 swap: movbu (0xa031e920),D0; jmp 0x60a8f71c; nine zeros.
SWAP = bytes.fromhex('fca820e931a0dc0e000000') + bytes(9)


def file_off(addr):
    return addr - BASE


def parse_listing(path):
    rows = []
    for line in path.read_text(encoding='utf-8').splitlines():
        if not line.strip() or line.startswith('??'):
            continue
        parts = line.split('\t')
        if len(parts) < 2:
            continue
        addr = int(parts[0], 16)
        raw = parts[1].strip()
        if not re.fullmatch(r'[0-9a-fA-F]+', raw):
            continue
        rows.append((addr, bytes.fromhex(raw), parts[2].strip() if len(parts) > 2 else ''))
    return rows


def main():
    image = IMAGE.read_bytes()
    lines = []
    home = parse_listing(HOME_LISTING)
    conv = parse_listing(CONV_LISTING)
    home_bad = []
    for addr, raw, text in home:
        got = image[file_off(addr):file_off(addr) + len(raw)]
        if got != raw:
            home_bad.append((addr, raw.hex(), got.hex(), text))
    conv_bad = []
    for addr, raw, text in conv:
        got = image[file_off(addr):file_off(addr) + len(raw)]
        if got != raw:
            conv_bad.append((addr, raw.hex(), got.hex(), text))
    lines.append(f'home instructions {len(home)} mismatches {len(home_bad)}')
    lines.append(f'converter instructions {len(conv)} mismatches {len(conv_bad)}')
    for row in home_bad + conv_bad:
        lines.append('MISMATCH ' + ' '.join(str(x) for x in row))

    stock_swap = image[file_off(SWAP_AT):file_off(SWAP_AT) + SWAP_LEN]
    lines.append('stock 0x60a8f708 ' + stock_swap.hex())
    # The listing's first instruction at the swap is the stock mov 0x9fa1.
    listed = b''.join(raw for addr, raw, _ in home if SWAP_AT <= addr < SWAP_AT + SWAP_LEN)
    lines.append('listing covers swap ' + (listed.hex() == stock_swap.hex()))

    z5 = {}
    with Z5_CSV.open(encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            z5[int(row['runtime_address'], 16)] = int(row['proposed_byte'], 16)
    over = bytearray(stock_swap)
    for i in range(SWAP_LEN):
        addr = SWAP_AT + i
        if addr in z5:
            over[i] = z5[addr]
    lines.append('overlay 0x60a8f708 ' + bytes(over).hex())
    lines.append('overlay matches documented swap ' + (bytes(over) == SWAP))

    # Keys named by the builder, searched in the stock builder window.
    window = image[file_off(0x60A8F6BB):file_off(0x60A8F7D5)]
    base = 0x60A8F6BB
    keys = {
        '0x9fa1': bytes.fromhex('a19f0000'),
        '0xdfa1': bytes.fromhex('a1df0000'),
        '0x99d2': bytes.fromhex('d2990000'),
        '0x1e01': bytes.fromhex('011e0000'),
        '0x5962': bytes.fromhex('62590000'),
        '0x88b2': bytes.fromhex('b2880000'),
        '0x1dd1': bytes.fromhex('d11d0000'),
        '0x9a41': bytes.fromhex('419a0000'),
    }
    for name, pat in keys.items():
        hits = []
        start = 0
        while True:
            i = window.find(pat, start)
            if i < 0:
                break
            hits.append(hex(base + i))
            start = i + 1
        lines.append(f'builder immediate {name} {hits or "none"}')

    # Converter jump table: index = type * 4, table at 0x60a7da08, 11 entries.
    table = 0x60A7DA08
    lines.append('converter jump table')
    for ui in range(11):
        ptr = struct.unpack_from('<I', image, file_off(table + ui * 4))[0]
        lines.append(f'  ui {ui} {ptr:#x}')

    # 0x1dd1 is the short mov 2c d1 1d. 0x1df1 is 2c f1 1d.
    conv_lo, conv_hi = 0x609B3ECD, 0x609B4200
    body = image[file_off(conv_lo):file_off(conv_hi)]
    for name, pat in (('0x1dd1', bytes.fromhex('2cd11d')), ('0x1df1', bytes.fromhex('2cf11d'))):
        start = 0
        while True:
            i = body.find(pat, start)
            if i < 0:
                break
            addr = conv_lo + i
            nxt = body[i + 3:i + 8]
            index = None
            if nxt[:2] == bytes.fromhex('9000') and len(nxt) >= 4 and nxt[2] == 0x85:
                index = nxt[3]
            elif nxt[:2] == bytes.fromhex('9000') and len(nxt) >= 3 and nxt[2] == 0x04:
                index = 0
            lines.append(f'converter {name} at {addr:#x} next {nxt.hex()} index {index}')
            start = i + 1

    # Stock menu strings that name Subject Detect / Off, UTF-16LE in the resource.
    res = (ROOT / 'inputs/02_0106_458c0020.decoded.bin').read_bytes()
    for needle in ('Subject Detection', 'Subject Detect', 'Face Priority', 'Human'):
        pat = needle.encode('utf-16le')
        n = res.count(pat)
        lines.append(f'resource utf16 {needle!r} count {n}')

    OUT.parent.mkdir(parents=True, exist_ok=True)
    text = '\n'.join(lines) + '\n'
    OUT.write_text(text, encoding='utf-8')
    OUT_CSV.write_bytes(Z5_CSV.read_bytes())
    print(text, end='')
    if home_bad or conv_bad or bytes(over) != SWAP:
        raise SystemExit(1)


if __name__ == '__main__':
    main()
